import re
from pathlib import Path
p=Path(__file__).resolve().parent/'gemini.py'
s=p.read_text(encoding='utf-8')
s=s.replace('生活系Threadsの完成原稿候補を作る。','家具・インテリアThreadsの完成原稿候補を作る。')
s=s.replace('投稿枠:E1=共感、P1=商品1、E2=共感、P2=商品2、E3=共感','投稿枠:E1=インテリア会話、P1=家具商品1、E2=インテリア会話、P2=家具商品2、E3=インテリア会話')
s=s.replace('共感投稿:\n- 誰にでも起こり得る具体的な日常場面と、その場で自然に出る本音・あるあるを書く。\n- 2〜3文、45〜140字。教訓、改善方法、商品への前振り、作ったようなオチは禁止。\n- 同時に作る共感枠は別テーマにし、掃除・収納・水回りは合計1件まで。','インテリア会話投稿:\n- 家具、模様替え、色、配置、照明、ラグ、寝具など部屋づくりの話だけを書く。\n- A/B、好み、短い気づきなどThreadsで反応しやすい形にする。\n- 一般生活あるある、掃除・家事ネタ、商品への前振りへ戻さない。')
new_block='''EMPATHY_FALLBACKS = (\n    ("家具の色", "インテリア/色", "neutral", "木目の家具なら、明るいオーク系と濃いウォールナット系どっち派？ 同じ形でも色で部屋の雰囲気がかなり変わるから、いつも迷う。"),\n    ("ソファ", "インテリア/ソファ", "neutral", "ソファはグレーとアイボリーならどっちを置きたい？ 見た目だけなら明るい色に惹かれるけど、毎日使う家具だと思うと迷う。"),\n    ("照明", "インテリア/照明", "positive", "夜の部屋って、家具より照明で印象が変わる気がする。天井照明を明るくするより、小さい灯りをいくつか置く部屋をつい見てしまう。"),\n    ("ラグ", "インテリア/ラグ", "neutral", "ラグは無地派？ 柄あり派？ ソファやテーブルがシンプルなら、足元だけ少し遊ぶのもかわいいと思ってる。"),\n    ("模様替え", "インテリア/模様替え", "positive", "部屋で一つだけ変えるなら、照明・ラグ・カーテンのどれを変える？ 大きい家具を買い替えなくても雰囲気が変わる三択。"),\n    ("ベッド周り", "インテリア/寝室", "neutral", "ベッド横は物を増やしたくないけど、小さいテーブルとライトだけは欲しい。寝る前に見る場所だから、ここだけ少し整えたくなる。"),\n)'''
s2,n=re.subn(r'EMPATHY_FALLBACKS = \(.*?\n\)\n\n\ndef _fallback_empathy_posts',new_block+'\n\n\ndef _fallback_empathy_posts',s,flags=re.S)
if n!=1: raise RuntimeError(f'fallback block replace count={n}')
p.write_text(s2,encoding='utf-8')
print('patched gemini.py')
